package com.company.platform.aigateway.api;import com.company.platform.aigateway.infrastructure.TenantContextProvider;import com.company.platform.aigateway.orchestration.*;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/ai") public class OrchestrationController{private final TenantContextProvider tenant;private final AICapabilityRegistry capabilities;private final PluginRegistry plugins;private final PluginLoader loader;private final ContextOrchestrator context;private final PolicyEngine policy;private final ContextCache cache;public OrchestrationController(TenantContextProvider t,AICapabilityRegistry c,PluginRegistry p,PluginLoader l,ContextOrchestrator x,PolicyEngine pe,ContextCache cc){tenant=t;capabilities=c;plugins=p;loader=l;context=x;policy=pe;cache=cc;}@GetMapping("/capabilities")public List<Map<String,Object>> capabilities(){return capabilities.list(tenant.currentTenantId());}@PostMapping("/capabilities")public Map<String,Object> capability(@RequestBody Map<String,String>b){return capabilities.register(tenant.currentTenantId(),b.get("name"),b.getOrDefault("version","v1"));}@GetMapping("/plugins")public List<PluginDescriptor> plugins(){return plugins.list(tenant.currentTenantId());}@PostMapping("/plugins")public PluginDescriptor plugin(@RequestBody Map<String,String>b){return plugins.register(loader.validate(new PluginDescriptor(UUID.randomUUID(),tenant.currentTenantId(),b.get("name"),b.getOrDefault("version","v1"),"REGISTERED",Map.of())));}@GetMapping("/policies")public Map<String,Object> policies(){return Map.of("tenantId",tenant.currentTenantId(),"policies",List.of());}@PostMapping("/policies")public Map<String,Object> policy(@RequestBody Map<String,Object>b){return Map.of("tenantId",tenant.currentTenantId(),"registered",false,"reason","policy persistence reserved for governance validation","data",b);}@GetMapping("/context")public Map<String,Object> context(){UUID t=tenant.currentTenantId();return context.normalize(t,List.of(Map.of("source","public-contracts","tenantId",t)));}@GetMapping("/pipeline")public Map<String,Object> pipeline(){return Map.of("tenantId",tenant.currentTenantId(),"status","READY","modelExecution","DISABLED","cache","AVAILABLE");}}
